<script lang="ts">
 import { language, languages, setLanguage, t, type TranslationKey } from './lib/i18n.svelte';
 import { onMount } from 'svelte';
 import { invoke, convertFileSrc, isTauri } from '@tauri-apps/api/core';
 import { listen } from '@tauri-apps/api/event';
 import { open, confirm } from '@tauri-apps/plugin-dialog';
 import { openPath, openUrl } from '@tauri-apps/plugin-opener';
 import { check, type Update } from '@tauri-apps/plugin-updater';
 import { relaunch } from '@tauri-apps/plugin-process';
 import { getCurrent } from '@tauri-apps/plugin-deep-link';
 import { IconSearch, IconPlus, IconRefresh, IconSettings, IconBox, IconFolder, IconLink, IconArrowUpRight, IconDownload, IconTrash, IconPencil, IconCommand, IconCheck, IconX, IconChevronRight } from '@tabler/icons-svelte';
 import type { Mod, Snapshot, Settings } from './lib/types';
 let data=$state<Snapshot|null>(null), query=$state(''), filter=$state('all'), selected=$state(''), busy=$state(false), error=$state(''), message=$state('');
 let settingsOpen=$state(false), draft=$state<Settings|null>(null), editOpen=$state(false), editName=$state(''), editDescription=$state('');
 let linkOpen=$state(false), link=$state(''), nexus=$state<{request_id:string;mod_id:number;file_id:number;url:string}|null>(null), update=$state<Update|null>(null);
 type NexusInfo={request_id:string;mod_id:number;file_id:number;url:string};
 let waitingLinks=$state<NexusInfo[]>([]);
 function activateLink(info:NexusInfo){nexus=info;downloaded=null;link='';linkOpen=true;}
 function showLink(info:NexusInfo){if(busy||updating||settingsOpen||editOpen||linkOpen){waitingLinks.push(info);return}activateLink(info);}
 let nexusKey=$state(''), downloadProgress=$state(''), downloaded=$state<{path:string;bytes:number;can_import:boolean}|null>(null);
 let updating=$state(false);
 $effect(()=>{if(!busy&&!updating&&!settingsOpen&&!editOpen&&!linkOpen&&waitingLinks.length)activateLink(waitingLinks.shift()!)});
 let updateStatus=$state<TranslationKey>('checkingUpdates');
 let input:HTMLInputElement;
 const filtered=$derived((data?.mods??[]).filter(m=>(filter==='all'||filter==='managed'&&m.managed||filter==='external'&&!m.managed||filter==='enabled'&&m.enabled)&&`${m.name} ${m.author} ${m.project}`.toLowerCase().includes(query.toLowerCase())));
 const errorMessage=$derived(error==='desktopRequired'?t('desktopRequired'):error);
 const active=$derived(filtered.find(m=>m.id===selected)??filtered[0]);
 async function run(action:()=>Promise<void>){if(busy||updating)return;busy=true;error='';message='';try{await action()}catch(e){error=String(e)}finally{busy=false}}
 async function refresh(){data=await invoke<Snapshot>('snapshot')}
 async function add(){await run(async()=>{const p=await open({directory:true,multiple:false,title:t('chooseImportFolder')});if(p){await invoke('import_folder',{path:p});await refresh();message='folderImported'}})}
 async function addZip(){await run(async()=>{const p=await open({multiple:false,filters:[{name:t('zipArchive'),extensions:['zip']}]});if(p){await invoke('import_zip',{path:p});await refresh();message='zipImported'}})}
 async function adopt(m:Mod){await run(async()=>{if(await confirm(t('adoptConfirm',{name:m.name}),{title:t('adoptTitle'),okLabel:t('confirm'),cancelLabel:t('cancel')})){await invoke('adopt_mod',{path:m.path});await refresh();message='adopted'}})}
 async function toggle(m:Mod){await run(async()=>{await invoke('toggle_mod',{id:m.id});await refresh()})}
 async function remove(m:Mod){await run(async()=>{if(await confirm(t('removeConfirm',{name:m.name}),{title:t('removeTitle'),kind:'warning',okLabel:t('confirm'),cancelLabel:t('cancel')})){await invoke('remove_mod',{id:m.id});await refresh()}})}
 async function updates(){
  if(updating||busy||settingsOpen||editOpen||linkOpen)return;
  updating=true;updateStatus='checkingUpdates';
  try{
   if(await invoke<boolean>('is_portable')){updateStatus='applyingUpdate';const applied=await invoke<boolean>('update_portable');if(!applied)updateStatus='upToDate';}
   else{update=await check({timeout:20000});if(update){updateStatus='applyingUpdate';await update.downloadAndInstall(undefined,{timeout:600000,restartAfterInstall:true});await relaunch();}else updateStatus='upToDate';}
  }catch(e){updateStatus='updateUnavailable';error=String(e)}finally{updating=false}
 }
 async function downloadNexus(){if(!nexus)return;await run(async()=>{downloaded=null;downloadProgress='connectingNexus';try{downloaded=await invoke('download_nxm',{requestId:nexus!.request_id,apiKey:nexusKey});message='downloadComplete';}finally{downloadProgress=''}})}
 async function receiveLink(raw:string){try{showLink(await invoke<NexusInfo>('parse_nxm',{link:raw}))}catch(e){error=String(e)}}
 onMount(()=>{if(!isTauri()){error='desktopRequired';return}
  refresh().catch(e=>error=String(e));void updates();const updateTimer=setInterval(()=>void updates(),60_000);invoke<{request_id:string;mod_id:number;file_id:number;url:string}[]>('pending_links').then(links=>{if(links.length){for(const info of links)showLink(info);}}).catch(e=>error=String(e));const progressUnlisten=listen<{request_id:string;received:number;total:number|null}>('nexus-download-progress',e=>{if(e.payload.request_id===nexus?.request_id)downloadProgress=e.payload.total?`${Math.round(e.payload.received/e.payload.total*100)}% · ${(e.payload.received/1048576).toFixed(1)} MB`:`${(e.payload.received/1048576).toFixed(1)} MB`;});const unlisten=listen<{request_id:string;mod_id:number;file_id:number;url:string}>('nexus-link',e=>showLink(e.payload));getCurrent().then(urls=>{for(const u of urls??[])if(u.startsWith('nxm:'))void receiveLink(u)}).catch(e=>error=String(e));return()=>{clearInterval(updateTimer);void unlisten.then(f=>f());void progressUnlisten.then(f=>f())};
 });
 function focusDialog(node:HTMLElement){const previous=document.activeElement as HTMLElement|null;const controls=()=>Array.from(node.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),textarea:not(:disabled),select:not(:disabled),[tabindex="0"]')).filter(el=>el.offsetParent!==null);queueMicrotask(()=>controls()[0]?.focus());const trap=(e:KeyboardEvent)=>{if(e.key!=='Tab')return;const all=controls();if(!all.length){e.preventDefault();return}const first=all[0],last=all[all.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===node||!node.contains(document.activeElement))){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||!node.contains(document.activeElement))){e.preventDefault();first.focus()}};node.addEventListener('keydown',trap);return{destroy(){node.removeEventListener('keydown',trap);if(previous?.isConnected)previous.focus()}};}
 function openSettings(){if(updating)return;draft=data?{...data.settings}:null;editOpen=false;linkOpen=false;settingsOpen=true;queueMicrotask(()=>document.querySelector<HTMLInputElement>('.modal input')?.focus());}
 function keyboard(e:KeyboardEvent){if((e.ctrlKey||e.metaKey)&&e.key===','){e.preventDefault();openSettings();return}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();if(!settingsOpen&&!editOpen&&!linkOpen)input?.focus();return}if(e.key==='Escape'){settingsOpen=false;linkOpen=false;editOpen=false}if(settingsOpen||editOpen||linkOpen)return;if(e.target instanceof HTMLInputElement||e.target instanceof HTMLTextAreaElement||e.target instanceof HTMLSelectElement)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const i=filtered.findIndex(m=>m.id===active?.id);selected=filtered[Math.max(0,Math.min(filtered.length-1,i+(e.key==='ArrowDown'?1:-1)))]?.id??''}}
</script>
<svelte:window onkeydown={keyboard}/>
<div class="shell">
 <aside>
  <div class="brand"><img src="/app-icon.png" alt=""/><div>inZOI<span>Better Mod Manager</span></div></div>
  <div class="section-label">{t('library')}</div>
  {#each [{id:'all',name:t('allMods'),icon:IconBox},{id:'enabled',name:t('enabled'),icon:IconCheck},{id:'managed',name:t('managedMods'),icon:IconFolder},{id:'external',name:t('externalMods'),icon:IconArrowUpRight}] as tab}
   <button class:chosen={filter===tab.id} onclick={()=>filter=tab.id}><tab.icon size={18}/>{tab.name}<small>{(data?.mods??[]).filter(m=>tab.id==='all'||tab.id==='enabled'&&m.enabled||tab.id==='managed'&&m.managed||tab.id==='external'&&!m.managed).length}</small></button>
  {/each}
  <div class="section-label space">{t('connections')}</div>
  <button disabled={updating} onclick={()=>{linkOpen=true;nexus=null;downloaded=null}}><IconLink size={18}/>{t('nexusLinks')}</button>
  <button onclick={()=>void updates()} disabled={busy||updating}><IconDownload size={18}/>{t('appUpdates')}</button><span class="update-status">{t(updateStatus,{version:update?.version??''})}</span>
  <div class="aside-bottom"><div class="game"><span class="game-dot"></span><div>inZOI<small>{t('localLibraryHint')}</small></div></div><button disabled={updating} onclick={openSettings}><IconSettings size={18}/>{t('settings')}<kbd>Ctrl ,</kbd></button></div>
 </aside>
 <main>
  <header><div class="search"><IconSearch size={20}/><input bind:this={input} bind:value={query} placeholder={t('searchPlaceholder')} aria-label={t('search')}/><kbd>Ctrl K</kbd></div><button class="icon" title={t('refresh')} disabled={busy||updating} onclick={()=>void run(refresh)}><IconRefresh size={18} class={busy?'spin':''}/></button></header>
  <div class="page-title"><div><div class="breadcrumb">{t('personalLibrary')} <IconChevronRight size={12}/> inZOI</div><h1>{filter==='external'?t('externalMods'):filter==='enabled'?t('enabled'):filter==='managed'?t('yourLibrary'):t('allMods')}</h1><p>{t('modCount',{count:filtered.length})}</p></div><div class="actions"><button disabled={busy||updating||!data} onclick={addZip}><IconDownload size={16}/>{t('importZip')}</button><button class="primary" disabled={busy||updating||!data} onclick={add}><IconPlus size={17}/>{t('addMod')}</button></div></div>
  {#if error}<div class="notice error" role="alert">{t('operationFailed')}: {errorMessage}<button class="icon" onclick={()=>error=''} aria-label={t('closeError')}><IconX size={16}/></button></div>{/if}
  {#if message}<div class="notice" role="status">{t(message as TranslationKey,{version:update?.version??''})}</div>{/if}
  {#if updating&&update}<div class="notice" role="status">{t('applyingUpdate')}</div>{/if}
  {#if data?.warnings.length}<details class="warnings"><summary>{t('scanWarnings',{count:data.warnings.length})}</summary>{#each data.warnings as warning}<p>{warning}</p>{/each}</details>{/if}
  <div class="workspace"><section class="mod-list" aria-label={t('modList')}><div class="list-head"><span>{t('modColumn')}</span><span>{t('status')}</span></div>
  {#each filtered as mod (mod.id)}<button class="mod-row" class:selected={active?.id===mod.id} onclick={()=>selected=mod.id}><div class="thumb">{#if mod.thumbnail}<img src={convertFileSrc(mod.thumbnail)} alt=""/>{:else}<IconBox size={25} stroke={1.25}/>{/if}</div><div class="mod-title"><strong>{mod.name||mod.project}</strong><span>{mod.author||t('unknownAuthor')} <span class="dot-sep">·</span> {mod.managed?t('privateLibrary'):t('inGame')}</span></div><span class:enabled={mod.enabled} class="status">{mod.enabled?t('enabled'):t('disabled')}</span></button>{/each}
  {#if filtered.length===0}<div class="empty"><IconBox size={42} stroke={1}/><h2>{query?t('noResults'):t('emptyTitle')}</h2><p>{query?t('noResultsHint'):t('emptyHint')}</p>{#if !query}<button onclick={add} disabled={!data||busy}>{t('chooseModFolder')} <IconArrowUpRight size={16}/></button>{/if}</div>{/if}
  </section><section class="inspector" aria-label={t('modDetails')}>{#if active}<div class="cover">{#if active.thumbnail}<img src={convertFileSrc(active.thumbnail)} alt={active.name}/>{:else}<IconBox size={66} stroke={0.8}/><span>inZOI / {active.project}</span>{/if}</div><div class="inspector-body"><span class="eyebrow">{active.managed?t('privateLibrary'):t('detectedInGame')}</span><h2>{active.name||active.project}</h2><p class="author">{t('byAuthor',{author:active.author||t('unknownAuthor')})}</p><p class="description">{active.description||t('noDescription')}</p><dl><div><dt>{t('version')}</dt><dd>{active.version||'—'}</dd></div><div><dt>{t('status')}</dt><dd>{active.enabled?t('enabled'):t('disabled')}</dd></div><div><dt>{t('managedBy')}</dt><dd>{active.managed?'Better Mod Manager':t('outsideApp')}</dd></div></dl>{#if active.managed}<button class="wide primary" disabled={busy||updating} onclick={()=>toggle(active!)}>{active.enabled?t('disableMod'):t('enableMod')}</button><div class="actions"><button disabled={updating} onclick={()=>{editName=active!.name;editDescription=active!.description;editOpen=true}}><IconPencil size={16}/>{t('edit')}</button><button class="danger" disabled={busy||updating||active.enabled} onclick={()=>remove(active!)}><IconTrash size={16}/>{t('remove')}</button></div>{:else}<div class="external-note">{t('externalNote')}</div><button class="primary wide" disabled={busy||updating} onclick={()=>adopt(active!)}>{t('takeControl')}</button><button class="wide" disabled={busy||updating} onclick={()=>void run(async()=>{await invoke('import_folder',{path:active!.path});await refresh();message='copied'})}>{t('copyToLibrary')}</button>{/if}<button class="wide ghost" onclick={()=>void run(async()=>{await openPath(active!.path)})}><IconFolder size={16}/>{t('openFolder')}</button>{#if active.source.startsWith('https://')}<button class="wide ghost" onclick={()=>void run(async()=>{await openUrl(active!.source)})}>{t('authorPage')} <IconArrowUpRight size={15}/></button>{/if}</div>{:else}<div class="inspector-empty"><IconCommand size={28} stroke={1}/><p>{t('selectMod')}</p></div>{/if}</section></div>
  <footer><span><span class="game-dot"></span>{updating?t('applyingUpdate'):busy?t('working'):t('localLibrary')}</span><span><kbd>↑</kbd><kbd>↓</kbd> {t('navigate')} <kbd>Ctrl K</kbd> {t('search')}</span></footer>
 </main>
</div>
{#if settingsOpen||editOpen||linkOpen}<div class="overlay"><div class="modal" use:focusDialog role="dialog" aria-modal="true" aria-label={settingsOpen?t('settings'):editOpen?t('editMod'):t('nxmTitle')} tabindex="-1"><div class="modal-head"><h2>{settingsOpen?t('librarySettings'):editOpen?t('editMod'):t('nexusLinks')}</h2><button class="icon" onclick={()=>{settingsOpen=false;editOpen=false;linkOpen=false}} aria-label={t('close')}><IconX size={20}/></button></div>
 {#if settingsOpen}<label>{t('language')}<select value={language.code} onchange={e=>setLanguage(e.currentTarget.value)}>{#each languages as option}<option value={option.code}>{option.name}</option>{/each}</select></label><p class="muted">{t('languageHint')}</p>{/if}
 {#if settingsOpen&&draft}<p class="muted">{t('settingsHint')}</p>{#each [{key:'mods_dir' as const,name:t('gameModsFolder')},{key:'library_dir' as const,name:t('libraryFolder')}] as f}<label>{f.name}<div class="path-input"><input bind:value={draft[f.key]}/><button title={t('chooseFolder')} onclick={()=>void run(async()=>{const p=await open({directory:true});if(p&&draft)draft[f.key]=p})}><IconFolder size={18}/></button></div></label>{/each}<p class="muted">{t('updateHint')}</p><button class="wide" onclick={()=>void run(async()=>{if(await confirm(t('nxmConfirm'),{title:t('nxmTitle'),okLabel:t('confirm'),cancelLabel:t('cancel')})){await invoke('register_nxm');message='nxmRegistered'}})}>{t('setNxmHandler')}</button><button class="primary wide" disabled={busy||updating} onclick={()=>void run(async()=>{await invoke('save_settings',{settings:draft});await refresh();settingsOpen=false})}>{t('saveSettings')}</button>
 {:else if editOpen}<label>{t('modName')}<input bind:value={editName}/></label><label>{t('description')}<textarea bind:value={editDescription} rows="5"></textarea></label><button class="primary wide" disabled={busy||updating} onclick={()=>void run(async()=>{await invoke('edit_mod',{id:active!.id,name:editName,description:editDescription});await refresh();editOpen=false})}>{t('saveChanges')}</button>
 {:else if linkOpen}<p class="muted">{t('linkHint')}</p><label>{t('link')}<input bind:value={link} placeholder="nxm://inzoi/mods/123/files/456"/></label><button class="primary wide" disabled={busy||updating} onclick={()=>receiveLink(link)}>{t('readLink')}</button>{#if waitingLinks.length}<button class="wide" disabled={busy||updating} onclick={()=>activateLink(waitingLinks.shift()!)}>{t('nextLink',{count:waitingLinks.length})}</button>{/if}{#if nexus}<div class="link-info">{t('linkInfo',{mod:nexus.mod_id,file:nexus.file_id})}</div><label>{t('nexusApiKey')}<input type="password" bind:value={nexusKey} autocomplete="off" placeholder={t('apiKeyPlaceholder')}/></label><p class="muted">{t('apiKeyHint')}</p><button class="primary wide" disabled={busy||updating||!nexusKey.trim()} onclick={downloadNexus}>{downloadProgress==='connectingNexus'?t('connectingNexus'):downloadProgress||t('downloadToLibrary')}</button>{#if downloaded}<div class="link-info">{t('downloadedSize',{size:(downloaded.bytes/1048576).toFixed(1)})}</div>{#if downloaded.can_import}<button class="wide" disabled={busy||updating} onclick={()=>void run(async()=>{await invoke('import_zip',{path:downloaded!.path});await refresh();message='downloadImported';linkOpen=false})}>{t('importDownloaded')}</button>{/if}<button class="wide" onclick={()=>void run(async()=>{await openPath(downloaded!.path.replace(/[\\/][^\\/]+$/,''))})}>{t('openDownloads')}</button>{/if}<button class="wide" onclick={()=>void run(async()=>{await openUrl(nexus!.url)})}>{t('openOnNexus')} <IconArrowUpRight size={16}/></button>{/if}{/if}
 {#if error}<p class="form-error" role="alert">{t('operationFailed')}: {errorMessage}</p>{/if}
 </div></div>{/if}
